def safe_join(base, user_path):
    if user_path.startswith('/'):
        raise ValueError("Absolute paths are not allowed")
    if user_path == '.' or user_path == '..':
        raise ValueError("Invalid path: .. is not allowed")
    normalized_path = user_path.replace('/', os.sep)
    if not normalized_path.startswith(os.sep):
        normalized_path = os.path.join(base, normalized_path)
    if normalized_path.startswith(base + os.sep) and \
       normalized_path != base + os.sep:
        return normalized_path
    else:
        raise ValueError("Path must be within the base directory")
